# Created by OpenAI
"""Shared MoE arithmetic, tile-layout, asynchronous-copy, and reduction primitives."""
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

@gluon.jit
def _weight_offset(n, k, K: gl.constexpr):
    return n // 16 * K * 16 + k // 16 * 256 + n % 16 * 16 + k % 16

@gluon.jit
def _sum(a, b):
    return a + b

@gluon.jit
def _copy_operands(asbuf, bsbuf, Q, W, aoff, boff):
    gl.amd.cdna4.async_copy.buffer_load_to_shared(asbuf, Q, aoff)
    gl.amd.cdna4.async_copy.buffer_load_to_shared(bsbuf, W, boff)
    gl.amd.cdna4.async_copy.commit_group()

@gluon.jit
def _prefetch_cached_weight(abuf, bbuf, X, W, aoff, boff, CACHE: gl.constexpr):
    gl.amd.cdna4.async_copy.buffer_load_to_shared(bbuf, W, boff, cache_modifier=CACHE)
    gl.amd.cdna4.async_copy.buffer_load_to_shared(abuf, X, aoff)
    gl.amd.cdna4.async_copy.commit_group()

@gluon.constexpr_function
def _projection_layout(dot, small, warps):
    scaled = dot == 'scaled_fp8'
    instruction = ([16, 16, 128] if small else [32, 32, 64]) if scaled else [16, 16, 32]
    mma = gl.amd.AMDMFMALayout(version=4, instr_shape=instruction, warps_per_cta=warps, transposed=True)
    return (mma, gl.DotOperandLayout(0, mma, 32 if scaled else 16), gl.DotOperandLayout(1, mma, 32 if scaled else 16))

@gluon.jit
def _scaled_dot(a, b, sa, sb, acc, DOT: gl.constexpr):
    zero = gl.full(acc.shape, 0, gl.float32, acc.type.layout)
    if DOT == 'scaled_fp8':
        partial = gl.amd.cdna4.mfma_scaled(a, None, 'e4m3', b, None, 'e4m3', zero)
    elif DOT == 'fp8':
        partial = gl.amd.cdna4.mfma(a, b, zero)
    else:
        gl.static_assert(DOT == 'bf16')
        partial = gl.amd.cdna4.mfma(a.to(gl.bfloat16), b.to(gl.bfloat16), zero)
    return acc + partial * sa[:, None] * sb[None, :]
